import os, json, numpy as np

N = 26
TOL = 1e-8
CROSS_PATH = 'storage/noesis/nmap/scientia_23_crossing_examples.json'
OUT_JSON   = 'storage/noesis/nmap/scientia_23_crossing_slacks.json'
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'

def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    else:
        centers = []
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float)
        r = np.full(N, 0.08, float)
    return c, r

def pair_slack(c, r, i, j):
    d = float(np.linalg.norm(c[i] - c[j]))
    return d - (r[i] + r[j])

def construct_packing():
    c, r = load_snapshot()
    try:
        data = json.load(open(CROSS_PATH, 'r'))
    except Exception:
        data = {'crossing_examples_strict': [], 'crossing_examples_inclusive': []}

    results = {'tol': TOL, 'motifs': []}
    for kind in ['crossing_examples_strict', 'crossing_examples_inclusive']:
        motifs = data.get(kind, []) or []
        for pairA, pairB in motifs:
            i, j = int(pairA[0]), int(pairA[1])
            k, l = int(pairB[0]), int(pairB[1])
            s1 = pair_slack(c, r, i, j)
            s2 = pair_slack(c, r, k, l)
            both_near_active = (s1 <= TOL) and (s2 <= TOL)
            results['motifs'].append({
                'type': 'strict' if kind.endswith('strict') else 'inclusive',
                'pairA': [i, j], 'pairB': [k, l],
                'slackA': float(s1), 'slackB': float(s2),
                'both_near_active@1e-8': bool(both_near_active)
            })

    try:
        os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
        with open(OUT_JSON, 'w') as f:
            json.dump(results, f, indent=2)
        print('SCI_23_SLACKS_JSON:', OUT_JSON)
        total = len(results['motifs'])
        sat = sum(1 for m in results['motifs'] if m['both_near_active@1e-8'])
        print('MOTIFS_EVAL total:', total, 'both_near_active:', sat)
    except Exception as e:
        print('LOG_WRITE_ERROR:', e)

    # Return baseline pack with tiny shrink
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
